function swimFrameLayout(path, frame) {
    const extra = registeredLayouts[path];
    if (extra) {
        const [x, y] = extra.shifts[frame] ?? [0, 0];
        return { originX: .5 + x / extra.cell, originY: .5 + y / extra.cell, scale: 1 };
    }
    const [x, y, scale] = layouts[path]?.[frame] ?? [0, 0, 1];
    return { originX: .5 + x / 96, originY: .5 + y / 96, scale: 1 / scale };
}

const plants = {
    'broadleaf-water-fern': 'normal',
    'purple-fork-seaweed': 'normal',
    'giant-fan-water-fern': 'rare',
};
// Keep the database's static decoration contract; reviewed plant sheets are bundled.
function primalPlantAsset(id, kind) {
    const folder = plants[id];
    return kind === 'decoration' && folder ? { path: `decorations/${folder}/${id}_sprite.png`, url: `/aquarium/plants/${id}_sprite.png` } : null;
}
function primalPlantFrame(id, time, reduced = false, editing = false) {
    return plants[id] ? reduced || editing ? 0 : Math.floor(Math.max(0, time) * 1.2) % 4 : null;
}

